"calculateTotalHours = function()
{
   var runCalc = function()
   {
   var g =ijf.main.controlSet["ijfContent_fld_5,2"]
   var d = g.control.items.items[0].store.getData();
   var total = 0;
   d.items.forEach(function(r)
   {
          total += r.data.timeestimate/1;
   });
   ijf.main.controlSet["ijfContent_fld_4,6"].control.items.items[0].update("Total Hours:  " + total);
   }
   //let the form paint then calc
   window.setTimeout(runCalc,500);
   return true;
}"

